examples.code:
const secret = Buffer.from('correct horse battery staple', 'utf8');

console.log(secret.length);              // 29 -- one byte per ASCII character here
console.log(secret.toString('hex'));     // raw bytes as hex
console.log(secret.toString('base64'));  // raw bytes as base64

const roundTrip = Buffer.from(secret.toString('base64'), 'base64');
console.log(roundTrip.equals(secret));   // true -- decoding base64 recovers the exact original bytes

// DANGEROUS: allocUnsafe does not zero-fill -- these bytes could be anything
function buildPacketUnsafe(payloadLength) {
  const packet = Buffer.allocUnsafe(4 + payloadLength);
  packet.writeUInt32BE(payloadLength, 0);   // writes bytes 0-3
  // BUG: forgot to write the payload into bytes 4 onward!
  return packet;   // bytes 4..end are still whatever memory happened to be there
}

// SAFE: alloc guarantees every byte starts at zero
function buildPacketSafe(payloadLength) {
  const packet = Buffer.alloc(4 + payloadLength);
  packet.writeUInt32BE(payloadLength, 0);
  return packet;   // any bytes not explicitly written are reliably 0, not leftover memory
}

function collectChunks(chunks) {
  const totalLength = chunks.reduce((sum, chunk) => sum + chunk.length, 0);
  const combined = Buffer.concat(chunks, totalLength);
  return combined.toString('utf8');
}

const incoming = [
  Buffer.from('{"name":'),
  Buffer.from('"Amy",'),
  Buffer.from('"age":30}'),
];

console.log(collectChunks(incoming));   // '{"name":"Amy","age":30}'
console.log(JSON.parse(collectChunks(incoming)));   // { name: 'Amy', age: 30 }

