sections.body:
The previous concept already introduced the mechanism; here's the exact contract. Every Writable stream has an internal buffer and a configured **highWaterMark** -- a threshold, in bytes by default, for how much unflushed data is considered 'a lot.' Calling writable.write(chunk) always accepts the chunk and queues it, regardless of the current buffer level, but its **return value** tells you whether you should keep going immediately (true) or should pause and wait (false, meaning the buffer is now at or above highWaterMark):

```javascript
function writeRespectingBackpressure(writable, chunks) {
  let i = 0;
  function writeNext() {
    let ok = true;
    while (i < chunks.length && ok) {
      ok = writable.write(chunks[i]);   // returns false once the buffer is full
      i++;
    }
    if (i < chunks.length) {
      // buffer is full -- stop writing, wait for 'drain' before resuming
      writable.once('drain', writeNext);
    }
  }
  writeNext();
}
```

Once write() returns false, the *correct* response is to stop calling write() on that stream entirely and wait for it to emit a 'drain' event -- which fires once the internal buffer has been flushed down to a level where it's ready to accept more. Continuing to call .write() anyway after a false return doesn't raise an error and doesn't reject anything -- Node will happily keep accepting more data into the buffer -- which is exactly the trap: nothing forces you to respect the signal, so ignoring it fails silently at first and expensively later.

The reason .pipe() (and stream.pipeline()) are recommended defaults, beyond the error-handling benefits covered in the previous concept, is that they implement exactly the write()-return-value-and-drain dance shown above, correctly, every time, without you having to write it yourself. When you write source.pipe(destination), internally .pipe() attaches a 'data' listener on source that calls destination.write(chunk); the moment that write() call returns false, .pipe() calls source.pause() to stop the flow of further 'data' events, and once destination emits 'drain', .pipe() calls source.resume() to let more chunks flow again. That's the entire backpressure story, handled for you, correctly, as long as you use .pipe()/pipeline() instead of hand-rolling 'data' event handling with direct .write() calls.

The risk is specifically in code that bypasses pipe() -- listening to 'data' events directly and calling .write() on some destination inside that handler, without checking the return value or listening for 'drain' at all:

```javascript
// DANGEROUS: never checks write()'s return value, never waits for 'drain'
readable.on('data', (chunk) => {
  writable.write(chunk);   // if writable can't keep up, this buffers unboundedly
});
```

This looks like it works in a quick manual test, because a small file or a fast destination never actually triggers a false return in the first place -- the bug is completely invisible until the data size or the destination's speed crosses the threshold where backpressure would actually kick in, which in production usually means 'the first time it really matters.'

examples.code:
const fs = require('fs');

function copyManually(sourcePath, destPath, onDone) {
  const source = fs.createReadStream(sourcePath);
  const dest = fs.createWriteStream(destPath);

  source.on('data', (chunk) => {
    const canContinue = dest.write(chunk);
    if (!canContinue) {
      source.pause();   // stop reading until dest catches up
    }
  });

  dest.on('drain', () => {
    source.resume();    // dest is ready for more -- resume reading
  });

  source.on('end', () => dest.end());
  dest.on('finish', onDone);
  source.on('error', (err) => dest.destroy(err));
  dest.on('error', (err) => { source.destroy(); onDone(err); });
}

const fs = require('fs');

// DANGEROUS: no return-value check, no pause/resume, no drain listener at all
function copyDangerously(sourcePath, destPath, onDone) {
  const source = fs.createReadStream(sourcePath);
  const dest = fs.createWriteStream(destPath);

  source.on('data', (chunk) => {
    dest.write(chunk);   // return value silently discarded
  });

  source.on('end', () => dest.end());
  dest.on('finish', onDone);
}

// Works perfectly in local testing with a small file and a fast local disk...
copyDangerously('./small-test-file.txt', './copy.txt', () => console.log('done'));
// ...but with a huge file and a slow destination (e.g. a network mount, a rate-limited
// upload), dest's internal buffer grows without bound because nothing ever tells
// `source` to pause -- memory usage climbs for the entire duration of the copy.

const fs = require('fs');

// Equivalent behavior to the manual, correct version above --
// but pipe() implements the write()/pause/drain/resume dance for you
function copyWithPipe(sourcePath, destPath, onDone) {
  fs.createReadStream(sourcePath)
    .pipe(fs.createWriteStream(destPath))
    .on('finish', onDone)
    .on('error', onDone);
}

copyWithPipe('./huge-file.bin', './copy-of-huge-file.bin', (err) => {
  if (err) return console.error('Copy failed:', err.message);
  console.log('Copy finished, memory usage stayed bounded throughout.');
});

