// Version A
function handleChunkA(readable, writable, chunk) {
  const ok = writable.write(chunk);
  if (!ok) {
    readable.pause();
    writable.once('drain', () => readable.resume());
  }
}

// Version B
function handleChunkB(readable, writable, chunk) {
  writable.write(chunk);   // return value ignored entirely
  // no pause, no drain listener
}

function streamChunksToDestination(chunks, destination, onDone) {
  for (const chunk of chunks) {
    destination.write(chunk);
  }
  destination.end(onDone);
}

exercises.solutionCode:
function streamChunksToDestination(chunks, destination, onDone) {
  let index = 0;

  function writeNext() {
    let ok = true;
    while (index < chunks.length && ok) {
      const isLast = index === chunks.length - 1;
      const chunk = chunks[index++];
      if (isLast) {
        destination.end(chunk, onDone);
        return;
      }
      ok = destination.write(chunk);
    }
    if (index < chunks.length) {
      destination.once('drain', writeNext);
    }
  }

  writeNext();
}
